package api

import "net/http"

func (s *Server) workersPage(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(brandedPage(shelledPage(workersPageHTML))))
}

const workersPageHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Timingdex · 处理节点</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101827;color:#edf3ff;font:15px ui-sans-serif,system-ui,-apple-system,sans-serif}header{padding:15px 6vw;border-bottom:1px solid #263651;display:flex;gap:18px;align-items:center;background:#101827ee}a{color:#b8c8ff;text-decoration:none}.brand{color:#fff;font-weight:800;margin-right:auto}.wrap{max-width:1120px;margin:auto;padding:38px 24px}.eyebrow{color:#8da7ff;font-weight:800;font-size:12px;letter-spacing:.09em}h1{font-size:clamp(30px,5vw,50px);letter-spacing:-.05em;margin:10px 0}.muted{color:#aab8d0;line-height:1.6}.head{display:flex;gap:18px;align-items:end;justify-content:space-between;flex-wrap:wrap;margin-bottom:18px}.head-actions{display:flex;gap:10px}.btn{padding:9px 14px;border-radius:9px;border:1px solid #354965;background:#182942;color:#edf3ff;cursor:pointer;font:inherit;font-size:14px}.btn.primary{background:#8ca7ff;border-color:#8ca7ff;color:#0c1422;font-weight:700;text-decoration:none;display:inline-block}.auth-callout{background:#4a3a17;color:#ffd9a0;border:1px solid #6b5425;border-radius:11px;padding:10px 14px;margin-bottom:16px;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.fleet-summary{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.fleet-pill{background:#172238;border:1px solid #2c3d5b;border-radius:10px;padding:8px 12px;font-size:13px;color:#c6d2ea}.fleet-pill b{color:#fff}.fleet-pill .ok{color:#70d7b1}.fleet-pill .warn{color:#ffc783}.fleet-pill .bad{color:#ff7b8a}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.panel{background:#172238;border:1px solid #2c3d5b;border-radius:15px;padding:18px}.panel h2{font-size:15px;margin:0 0 12px;color:#fff}.empty{color:#8fa1bf;padding:18px 6px;font-size:14px}.empty .btn{margin-top:10px}.pill{display:inline-block;padding:1px 8px;border-radius:99px;font-size:11px;font-weight:700;background:#263651;color:#c6d2ea}.pill.compat-ok{background:#1e4d3a;color:#70d7b1}.pill.compat-warn{background:#4a3a17;color:#ffc783}.pill.compat-bad{background:#4a1e24;color:#ff7b8a}.node{background:#0e1728;border:1px solid #2c3d5b;border-radius:12px;padding:14px;margin-bottom:10px}.node .top{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap}.node .name{font-weight:800}.node .meta{color:#9fb0ce;font-size:13px;margin-top:6px;line-height:1.7}.failure{color:#ff7b8a}.job{background:#0e1728;border:1px solid #2c3d5b;border-radius:12px;padding:14px;margin-bottom:10px}.job .top{display:flex;gap:10px;justify-content:space-between;align-items:center}.job .name{font-weight:800}.job .meta{color:#9fb0ce;font-size:13px;margin-top:6px;line-height:1.7}.bar{height:5px;background:#263651;border-radius:3px;margin-top:5px;overflow:hidden}.bar i{display:block;height:100%;background:#8ca7ff}.assign{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}.assign select{flex:1;min-width:120px;padding:8px;border:1px solid #354965;border-radius:8px;background:#0e1728;color:#fff;font:inherit}.assign .btn{padding:8px 12px;font-size:13px}.token{background:#0e1728;border:1px solid #2c3d5b;border-radius:10px;padding:10px 12px;margin-top:10px;font:13px ui-monospace,Menlo,monospace;word-break:break-all;color:#c6d2ea}.details-wrap{margin-top:16px}.details-wrap details{background:#172238;border:1px solid #2c3d5b;border-radius:12px;padding:12px 14px}.details-wrap summary{cursor:pointer;color:#c6d2ea;font-size:14px}.details-wrap .token-actions{display:flex;gap:8px;align-items:center;margin-top:10px;flex-wrap:wrap}.notice{color:#9fb0ce;font-size:12px;margin-top:8px}.status{color:#70d7b1;font-size:13px;margin-top:8px}
@media(max-width:760px){.grid{grid-template-columns:1fr}}
</style></head><body data-workers-page><!--SHELL_HEADER--><main class="wrap"><div class="head"><div><div class="eyebrow">WORKER FLEET</div><h1>处理节点</h1><p class="muted">Hub 只负责调度和保存成果；节点在自己的机器上处理挂载素材。离线节点不会丢失已上传的预览文件。</p></div><div class="head-actions"><a class="btn primary" href="/worker-setup">添加 Worker</a><button type="button" class="btn" id="refresh">刷新</button></div></div><div class="auth-callout" id="auth-callout" hidden><span>需要 Hub 管理 Token 才能查看节点与任务。</span><button type="button" class="btn" id="login-prompt">登录以查看</button></div><div class="fleet-summary" id="fleet-summary" hidden></div><div class="grid"><section class="panel"><h2>处理节点</h2><div id="workers" class="empty">加载中…</div></section><section class="panel"><h2>工作流进度</h2><div id="jobs" class="empty">加载中…</div></section></div><div class="details-wrap"><details id="advanced-pairing"><summary>高级：只生成一次性配对 Token</summary><p class="notice">适合命令行熟练者。完整向导在 <a href="/worker-setup">安装向导</a>。Token 只保留在当前页面内存中，不会写进浏览器存储。</p><button type="button" class="btn" id="pairing-btn">生成配对 Token</button><div id="pairing" class="token" hidden></div></details></div></main>
<script>
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function node(w){const c=w.capabilities||{},online=w.status==='online',compat=w.compat||{};const caps=[c.proxy?'Proxy':'',c.thumbnail?'缩略图':'',c.audio_extract?'音频':''].filter(Boolean).join(' · ')||'只上报状态';const roots=(c.library_roots||[]).join('、')||'未挂载素材库';const hardware=(c.hardware||[]).join('、')||'软件编码（无硬件加速）';const vmap={compatible:['兼容','compat-ok'],upgrade_recommended:['建议升级','compat-warn'],incompatible:['不兼容','compat-bad']};const vp=vmap[compat.verdict]||['未知','compat-warn'];const vline='<br>版本：'+esc(compat.worker_version||'未知')+' <span class="pill '+vp[1]+'">'+vp[0]+'</span>';const vnote=(compat.verdict==='incompatible')?'<br><span class="failure">'+esc(compat.message||'该节点与本 Hub 不兼容')+'；不派发任务</span>':'';return '<article class="node"><div class="top"><span class="name">'+esc(w.name||w.id)+'</span><span class="pill '+vmap[compat.verdict]?vp[1]:'compat-ok'+'">'+(online?'在线':'离线')+'</span></div><div class="meta">'+esc(w.platform||'未知平台')+' · '+caps+'<br>素材：'+roots+'<br>编码：'+hardware+vline+vnote+'</div></article>'}
let knownWorkers=[];
function job(j){const stage=j.current_stage||'等待调度';const progress=Number.isFinite(Number(j.progress))?Number(j.progress):0;const attempt=Number.isFinite(Number(j.attempt_count))?Number(j.attempt_count):0;const maxAttempts=Number.isFinite(Number(j.max_attempts))?Number(j.max_attempts):0;const options=['<option value="">自动选择兼容节点</option>'].concat(knownWorkers.map(w=>'<option value="'+esc(w.id)+'" '+((j.assigned_worker_id===w.id||j.preferred_worker_id===w.id)?'selected':'')+'>'+esc(w.name||w.id)+'</option>')).join('');const failure=j.last_error_message?'<br><span class="failure">最近失败：'+esc(j.last_error_message)+'</span>':'';const canAssign=j.job_type==='derive';return '<article class="job"><div class="top"><span class="name">'+esc(j.job_type)+' · '+esc(j.asset_id)+'</span><span class="pill">'+esc(j.state)+'</span></div><div class="meta">'+esc(stage)+' · '+Math.round(progress)+'%<div class="bar"><i style="width:'+Math.min(100,Math.max(0,progress))+'%"></i></div>尝试 '+attempt+'/'+maxAttempts+(j.lease_owner?'<br>执行节点：'+esc(j.lease_owner):'')+failure+'</div>'+(canAssign?'<div class="assign"><select id="assignment-'+esc(j.job_id)+'">'+options+'</select><button class="btn" data-action="assign" data-mode="preferred" data-job-id="'+esc(j.job_id)+'">优先使用（可回退）</button><button class="btn" data-action="assign" data-mode="required" data-job-id="'+esc(j.job_id)+'">锁定到此节点</button></div>':'')+'</article>'}
function csrfToken(){const prefix='__Host-timingdex_csrf=';const item=document.cookie.split('; ').find(function(x){return x.indexOf(prefix)===0});return item?decodeURIComponent(item.slice(prefix.length)):''}
function hubFetch(url,options={}){const headers=new Headers(options.headers||{});const csrf=csrfToken();if(csrf)headers.set('X-CSRF-Token',csrf);return fetch(url,{...options,credentials:'same-origin',headers});}
async function apiErrMsg(r){try{const d=await r.json();if(d&&d.error&&d.error.message)return d.error.action?(d.error.message+'（'+d.error.action+'）'):d.error.message}catch(_){}return (await r.text()).trim()}
async function json(response){if(!response.ok){if(response.status===401)throw new Error('unauthorized');throw new Error(await apiErrMsg(response))}return response.json()}
function statusText(msg){const el=document.getElementById('pairing');if(el&&!el.hidden)el.textContent=msg}
function showAuthCallout(){document.getElementById('auth-callout').hidden=false;document.getElementById('fleet-summary').hidden=true;document.getElementById('workers').innerHTML='<div class="empty">登录后可查看处理节点。</div>';document.getElementById('jobs').innerHTML='<div class="empty">登录后可查看处理任务。</div>'}
function hideAuthCallout(){document.getElementById('auth-callout').hidden=true}
document.getElementById('login-prompt').addEventListener('click',function(){const f=document.querySelector('.shell-auth input');if(f)f.focus()});
async function createPairing(){const b=document.getElementById('pairing-btn');b.disabled=true;const out=document.getElementById('pairing');out.hidden=false;out.textContent='正在生成…';try{const pairing=await hubFetch('/api/v1/hub/worker-pairings',{method:'POST'}).then(json);out.innerHTML='一次性配对 Token（'+esc(pairing.expires_at?'15 分钟内有效':'一次性')+'）：<br>'+esc(pairing.token)+'<div class="token-actions"><button type="button" class="btn" data-copy="'+esc(pairing.token)+'">复制</button><a class="btn" href="/worker-setup">前往完整安装向导</a></div>'}catch(e){out.textContent='无法生成配对 Token：'+e.message}finally{b.disabled=false}}
document.getElementById('pairing-btn').addEventListener('click',createPairing);
document.addEventListener('click',function(e){const b=e.target.closest('[data-copy]');if(!b)return;navigator.clipboard.writeText(b.dataset.copy).then(function(){b.textContent='已复制';setTimeout(function(){b.textContent='复制'},1500)}).catch(function(){prompt('复制配对 Token',b.dataset.copy)})});
async function assignJob(jobID,mode){const workerID=document.getElementById('assignment-'+jobID).value;try{await hubFetch('/api/v1/admin/worker-jobs/'+encodeURIComponent(jobID)+'/assignment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({worker_id:workerID,mode})}).then(json);load()}catch(e){alert('无法更新节点偏好：'+e.message)}}
document.addEventListener('click',function(e){const b=e.target.closest('[data-action="assign"]');if(b)assignJob(b.dataset.jobId,b.dataset.mode)});
async function load(){let workers,jobs;try{const results=await Promise.all([hubFetch('/api/v1/hub/workers').then(json),hubFetch('/api/v1/jobs?limit=100').then(json)]);workers=results[0];jobs=results[1]}catch(e){if(String(e.message)==='unauthorized'){showAuthCallout()}else{document.getElementById('workers').innerHTML='<div class="empty">无法读取节点：'+esc(e.message)+'</div>';document.getElementById('jobs').innerHTML='<div class="empty">无法读取任务：'+esc(e.message)+'</div>'}return}hideAuthCallout();knownWorkers=Array.isArray(workers)?workers:[];const detailed=await Promise.all((Array.isArray(jobs)?jobs:[]).map(async j=>{try{return await hubFetch('/api/v1/admin/worker-jobs/'+encodeURIComponent(j.id)).then(json)}catch(_){return j}}));const wl=Array.isArray(workers)?workers:[];const on=wl.filter(x=>x.status==='online').length,off=wl.length-on,incompat=wl.filter(x=>(x.compat||{}).verdict==='incompatible').length;const running=detailed.filter(j=>j.state==='running').length;document.getElementById('fleet-summary').innerHTML='<span class="fleet-pill">在线 <b class="ok">'+on+'</b></span><span class="fleet-pill">离线 <b class="warn">'+off+'</b></span><span class="fleet-pill">不兼容 <b class="bad">'+incompat+'</b></span><span class="fleet-pill">运行任务 <b>'+running+'</b></span>';document.getElementById('fleet-summary').hidden=false;document.getElementById('workers').innerHTML=wl.length?wl.map(node).join(''):'<div class="empty">还没有处理节点。点击右上角「添加 Worker」打开安装向导。<div><a class="btn primary" href="/worker-setup">打开安装向导</a></div></div>';document.getElementById('jobs').innerHTML=detailed.length?detailed.map(job).join(''):'<div class="empty">没有等待或运行中的任务。</div>'}
document.getElementById('refresh').addEventListener('click',load);
window.addEventListener('timingdex:admin-auth-changed',load);
load();setInterval(load,15000);
</script></body></html>`
